mapper.select:
SELECT id, template_id, business_domain_id, instance_domain_role_id, sync_mode, applied_at, updated_at
FROM role_template_domain
WHERE template_id = #{templateId}
  AND business_domain_id = #{domainId}
LIMIT 1

SELECT COUNT(*)
FROM role_template_domain
WHERE template_id = #{templateId}

mapper.delete:
DELETE FROM role_template_domain
WHERE template_id = #{templateId}
  AND business_domain_id = #{domainId}

mapper.update:
